  "translations": {
    "cs": {
      "representative_place": "Historické centrum Podunajských Biskupic – Trojičné námestie",
      "facts": [
        {
          "id": "fact_001",
          "title": "Kostel svatého Mikuláše – středověké jádro",
          "text": "Farní kostel svatého Mikuláše patří k nejstarším dochovaným stavbám Podunajských Biskupic. Vznik se tradičně klade do roku 1221, ale přímý doklad o stavbě v tomto roce chybí; farnost je bezpečně doložena papežskou listinou z roku 1254. Jádro, svatyně, sakristie a věž pocházejí ze 13. století. Výrazné úpravy proběhly v letech 1751–1755 a při rozšíření o dvě boční lodě v roce 1937."
        },
        {
          "id": "fact_002",
          "title": "Římský milník císaře Alexandra Severa",
          "text": "Kamenný milník z 3. století, spojovaný s císařem Alexandrem Severem a datovaný do roku 230 n. l., dokládá římskou minulost oblasti. Originál byl nalezen v prostoru někdejší arcibiskupské zahrady. V zeleném pásu na Biskupické ulici stojí od roku 1996 jeho kopie, nikoli původní antický kámen."
        },
        {
          "id": "fact_003",
          "title": "Trojičný sloup – dominanta historického náměstí",
          "text": "Trojičný sloup byl vztyčen roku 1730 a dal jméno hlavnímu veřejnému prostranství Podunajských Biskupic. Kanelovaný sloup vrcholí sousoším Nejsvětější Trojice a u paty má starší barokní sochy. A. Brandl jej obnovoval v letech 1851 a 1886; další restaurátorský zásah proběhl v roce 2016. Jde o národní kulturní památku."
        },
        {
          "id": "fact_004",
          "title": "Kúria Juraja Alberta – šlechtické sídlo a Muzeum obchodu",
          "text": "Kúrii nechal kolem poloviny 18. století postavit Juraj Albert, hlavní finanční správce bratislavského arcibiskupského panství. K sídlu patřil několikahektarový park, z něhož se dochovala část kaštanové aleje. Po Albertově smrti přešla kúria přes jeho zetě Antona Galgóczyho k rodině Linzbóth. Po válce sloužila veřejným účelům a od roku 1988 v ní sídlí Muzeum obchodu."
        },
        {
          "id": "fact_005",
          "title": "Letní zámeček kardinála Batthyányho v Lieskovci",
          "text": "Kardinál József Batthyány nechal kolem poloviny 18. století v Lieskovci vybudovat letní sídlo určené pro oslavy, společenská setkání a taneční zábavy. Dvoupatrový zámeček měl asi osmnáct pokojů a několik tanečních sálů; roku 1783 dostal malby s čínskými motivy. V 19. století chátral, později sloužil jako sklad a po válce byl součástí drůbežářské farmy."
        },
        {
          "id": "fact_006",
          "title": "Sestra Zdenka Schelingová a poutní kostel Povýšení svatého Kříže",
          "text": "Podunajské Biskupice byly centrem slovenské provincie Milosrdných sester svatého Kříže. Cecília Schelingová vstoupila do mateřského domu roku 1931, přijala jméno Zdenka a první řeholní sliby složila roku 1937. Komunistický režim sestry v roce 1950 násilně vyvezl; později zde vznikl ústav tuberkulózy. Kostel byl znovu vysvěcen roku 1992 a od blahoslavení Zdenky v roce 2003 je hlavním poutním kostelem s jejími relikviemi."
        },
        {
          "id": "fact_007",
          "title": "Pamětní sloup vysídlených maďarských rodin",
          "text": "U základní školy na Vetvárské ulici stojí řezbářsky zdobený dřevěný sloup na památku maďarských rodin, které musely proti své vůli opustit Podunajské Biskupice. Je na něm letopočet 1947 a nápis In memoriam. Místní historický přehled uvádí, že roku 1946 bylo do českých zemí násilně odvlečeno 140 biskupických maďarských rodin. Památník byl odhalen 6. října 2007."
        }
      ]
    },
    "de": {
      "representative_place": "Historisches Zentrum von Podunajské Biskupice – Trojičné námestie",
      "facts": [
        {
          "id": "fact_001",
          "title": "St.-Nikolaus-Kirche – mittelalterlicher Kern",
          "text": "Die Kirche gehört zu den ältesten erhaltenen Bauten des Ortes. Die Gründung wird traditionell auf 1221 datiert, doch ein direkter Baunachweis fehlt; eine päpstliche Urkunde belegt die Pfarrei 1254. Kern, Sakristei und Turm stammen aus dem 13. Jahrhundert. Größere Umbauten erfolgten 1751–1755 und 1937."
        },
        {
          "id": "fact_002",
          "title": "Römischer Meilenstein von Severus Alexander",
          "text": "Ein Meilenstein des 3. Jahrhunderts, verbunden mit Kaiser Severus Alexander und datiert auf 230 n. Chr., belegt die römische Vergangenheit. Das Original wurde im ehemaligen erzbischöflichen Garten gefunden. An der Biskupická-Straße steht seit 1996 eine Kopie."
        },
        {
          "id": "fact_003",
          "title": "Dreifaltigkeitssäule – Wahrzeichen des Platzes",
          "text": "Die 1730 errichtete Säule gab dem Trojičné námestie seinen Namen. Sie trägt eine Gruppe der Heiligsten Dreifaltigkeit und ältere barocke Figuren. A. Brandl restaurierte sie 1851 und 1886; 2016 erfolgte eine weitere Restaurierung. Sie ist ein nationales Kulturdenkmal."
        },
        {
          "id": "fact_004",
          "title": "Kúria von Juraj Albert und Handelsmuseum",
          "text": "Juraj Albert ließ das Herrenhaus um die Mitte des 18. Jahrhunderts errichten. Zum Anwesen gehörte ein großer Park, von dem ein Teil der Kastanienallee erhalten ist. Später kam es an die Familie Linzbóth. Seit 1988 befindet sich hier das Handelsmuseum."
        },
        {
          "id": "fact_005",
          "title": "Sommerpalais von Kardinal Batthyány in Lieskovec",
          "text": "Kardinal Batthyány ließ um 1750 ein Sommerpalais für Feste und Tanzveranstaltungen errichten. Es hatte etwa 18 Räume und mehrere Tanzsäle; 1783 erhielt es Malereien mit chinesischen Motiven. Später verfiel es und diente als Lager und Geflügelfarm."
        },
        {
          "id": "fact_006",
          "title": "Schwester Zdenka und die Wallfahrtskirche zur Kreuzerhöhung",
          "text": "Cecília Schelingová trat 1931 in das Mutterhaus der Schwestern vom Heiligen Kreuz ein und legte 1937 ihre ersten Gelübde ab. 1950 wurden die Schwestern gewaltsam entfernt. Die Kirche wurde 1992 neu geweiht und ist seit Zdenkas Seligsprechung 2003 Wallfahrtskirche mit ihren Reliquien."
        },
        {
          "id": "fact_007",
          "title": "Gedenksäule für vertriebene ungarische Familien",
          "text": "Bei der Schule in der Vetvárska-Straße steht eine geschnitzte Gedenksäule für ungarische Familien, die den Ort verlassen mussten. Sie trägt die Jahreszahl 1947 und „In memoriam“. Eine Ortschronik berichtet von 140 Familien, die 1946 gewaltsam in die böhmischen Länder deportiert wurden. Das Denkmal wurde 2007 enthüllt."
        }
      ]
    },
    "en": {
      "representative_place": "Historic centre of Podunajské Biskupice – Trojičné námestie",
      "facts": [
        {
          "id": "fact_001",
          "title": "St Nicholas Church – the medieval core",
          "text": "The church is among the oldest surviving buildings in the area. Its foundation is traditionally dated to 1221, but no direct proof confirms that year; a papal charter documents the parish in 1254. The core, sacristy and tower date from the 13th century. Major alterations followed in 1751–1755 and 1937."
        },
        {
          "id": "fact_002",
          "title": "The Roman milestone of Severus Alexander",
          "text": "A 3rd-century milestone associated with Emperor Severus Alexander and dated to AD 230 documents the Roman past of the area. The original was found in the former archbishop’s garden. A replica was installed on Biskupická Street in 1996."
        },
        {
          "id": "fact_003",
          "title": "The Holy Trinity Column – landmark of the square",
          "text": "Erected in 1730, the column gave its name to Trojičné námestie. It is crowned by a sculptural group of the Holy Trinity and has older Baroque statues at its base. A. Brandl restored it in 1851 and 1886; it was restored again in 2016. It is a national cultural monument."
        },
        {
          "id": "fact_004",
          "title": "The Juraj Albert Manor and Museum of Trade",
          "text": "Juraj Albert built the manor around the mid-18th century. Its grounds once included a large park, part of whose chestnut avenue survives. The manor later passed to the Linzbóth family. Since 1988 it has housed the Museum of Trade."
        },
        {
          "id": "fact_005",
          "title": "Cardinal Batthyány’s summer palace at Lieskovec",
          "text": "Around the mid-18th century Cardinal Batthyány built a summer palace for celebrations and dances. It had about eighteen rooms and several dance halls; in 1783 its interior received paintings with Chinese motifs. It later deteriorated and served as a warehouse and poultry farm."
        },
        {
          "id": "fact_006",
          "title": "Sister Zdenka and the Pilgrimage Church of the Exaltation of the Holy Cross",
          "text": "Cecília Schelingová entered the Sisters of the Holy Cross mother house in 1931 and made her first vows in 1937. The communist regime forcibly removed the sisters in 1950. The church was reconsecrated in 1992 and became the main pilgrimage church holding Zdenka’s relics after her beatification in 2003."
        },
        {
          "id": "fact_007",
          "title": "Memorial pillar to displaced Hungarian families",
          "text": "A carved wooden pillar beside the school on Vetvárska Street commemorates Hungarian families forced to leave the area. It bears 1947 and “In memoriam”. A local history records that 140 families were forcibly deported to the Czech lands in 1946. The memorial was unveiled in 2007."
        }
      ]
    },
